mapper.update:
update ${tableName}
set last_sync_time = date_add(utc_timestamp(), interval 8 hour), last_sync_time_utc = utc_timestamp(),
    hit_count = hit_count + 1, update_by = #{updateBy},
    update_time = date_add(utc_timestamp(), interval 8 hour), update_time_utc = utc_timestamp()
where version_id = #{versionId}

mapper.select:

where biz_key = #{bizKey}
order by last_sync_time desc, version_id desc
limit 1

select version_id, biz_key, content_hash, first_sync_time, first_sync_time_utc, last_sync_time,
       last_sync_time_utc, hit_count, create_by, create_time, create_time_utc, update_by, update_time,
       update_time_utc, remark
from ${tableName}

    and biz_key = #{bizKey}

order by version_id desc

select sync_id, info_key, biz_key, http_status, result, version_id, raw_bytes, cost_ms, message,
       trigger_type, sync_time, sync_time_utc, create_by, create_time
from option_info_sync

    and info_key = #{infoKey}
    and biz_key = #{bizKey}
    and result = #{result}

order by sync_id desc
